package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class DataQualityActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Data Quality Command View","AcreNex makes record quality visible instead of hiding fragmented-data problems.");DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT ulpin,completeness,consistency,spatial_accuracy,timeliness,status FROM data_quality",null);try{while(c.moveToNext()){LinearLayout box=utils.column(this);box.addView(utils.text(this,"ULPIN  "+c.getString(0),17,utils.TEXT,true));utils.row(box,this,"Completeness",c.getDouble(1)+"%");utils.row(box,this,"Consistency",c.getDouble(2)+"%");utils.row(box,this,"Spatial accuracy",c.getDouble(3)+"%");utils.row(box,this,"Timeliness",c.getDouble(4)+"%");utils.row(box,this,"Quality status",c.getString(5));utils.addCard(root,box,this);}}finally{c.close();}utils.setScreenContentView(this, root);}
}
